INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('58a2a723-a8a3-44cf-9acb-7d799ed70a2d', 'b2b2b2b2-3030-4000-8000-000000000002', 22, 'Dia 22 — Recomeço', 'Semana 4: Integrar', '{"pch": "As miseric\u00f3rdias do Senhor renovam-se cada manh\u00e3\u2026 Cada dia \u00e9 um novo come\u00e7o.", "verse": "Lm 3,22-23", "lectio": "Leia Lm 3,19-26. Esperan\u00e7a no meio da ru\u00edna.", "practice": "Comece algo novo hoje \u2014 mesmo pequeno.", "question": "O que voc\u00ea gostaria de recome\u00e7ar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;